#!/usr/bin/env bash
#
# Self-test for rehearse.sh's fail-closed source binding.
#
# Builds throwaway repositories shaped like the dispatched checkout and like
# the CI build image's tree — context-excluded paths absent, the gen/
# binding and _address families regenerated from artifacts, gitignored build
# outputs present, the committed ignore rules dropped — and proves the
# verifier accepts exactly the image's documented construction and nothing
# else, and that no regenerated byte survives verification: every
# regenerated family is checked restored on disk to the committed bytes,
# arbitrary contents included, while an unrestorable path, an untracked
# injection, and every tamper of committed code fail.
#
# All of that rests on a classification of the build context written out in
# rehearse.sh, so the last cases prove that classification still matches the
# rules the build's own ignore file carries. They commit the checked-in
# rules, rewritings of them, and drifts of them into throwaway trees, and
# require the mirror check to accept the rules as they stand and as spellings
# only path cleaning resolves; to refuse a dropped rule, an added rule, a
# dropped re-inclusion, an absent or ruleless file, and every pattern
# construct it does not model; and to read its rules from the file the
# builder itself would select, which a committed Dockerfile.dockerignore
# takes over from the root .dockerignore entirely.
#
# Which file that is, in turn, is selected by a Dockerfile named in a workflow
# rather than in this scaffold, so the next cases move the real build step onto
# another Dockerfile and another context and require the resolution to follow
# it, the path filters that gate this whole check to be held to it, and every
# step shape the resolution does not model to be refused rather than guessed
# at.
#
# All of that in turn rests on that gate running, so the last cases hold the
# reading of when it does: one removal per class of input the requirement is
# derived from, filters read in order so a listing a later entry negates is
# not coverage, patterns whose grammar this scaffold has no reading for
# refused, and the trigger shapes — push without a pull request, a restricted
# base branch, a narrowed activity type list — that let a change merge with
# the gate never having run on it. And because none of that says the gate
# does anything once reached, the last of them drop, duplicate, condition and
# excuse the analysis run itself, then take away the thing a search for
# matching text would have called a run and left standing: the invocation
# named rather than executed, printed, captured, piped, excused in shell,
# conditioned in shell, read without executing, outranked by a later command,
# handed to another interpreter, or written by an expression the runner fills
# in. Runs anywhere bash and git exist; everything lives under mktemp and
# this repository is only ever read.

set -euo pipefail

TEST_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# shellcheck source=/dev/null
source "${TEST_DIR}/rehearse.sh"

# The verifier reads these from the environment; the container running the
# proof stages exports them, and they must never leak into the cases.
unset PR4109_EXPECTED_SOURCE_COMMIT PR4109_SOURCE_BINDING_MODE

# The build rules the mirror cases compare against, resolved once here: the
# cases below reassign REPO_ROOT inside their subshells to point the verifier
# at a throwaway tree, so the checked-in file has to be named before any of
# them runs.
CHECKED_IN_DOCKERIGNORE="${REPO_ROOT}/.dockerignore"

WORK="$(mktemp -d "${TMPDIR:-/tmp}/pr4109-source-binding.XXXXXX")"
trap 'rm -rf "${WORK}"' EXIT

PASS=0
FAILED=0
ORIGIN_SHA=""
CASE_RC=0
CASE_OUT=""

# Every git invocation pins its identity and disables signing so the cases
# behave identically on a workstation and inside the CI build image.
git_q() {
  git -c user.name=rehearsal -c user.email=rehearsal@invalid \
    -c commit.gpgsign=false -c init.defaultBranch=main "$@"
}

# The build step and the path filters a fixture carries unless a case is
# proving a drift in one of them: the shape the checked-in workflows have,
# reduced to what the resolution actually reads out of them.
DEFAULT_BUILD_STEP="        uses: ${BUILD_ACTION}@v5
        with:
          target: build-docker
          load: true
          context: ."
DEFAULT_PATH_FILTERS="${SCAFFOLD_DIR}/**
${REHEARSAL_WORKFLOW}
${SCAFFOLD_LINT_WORKFLOW}
${CONTRACTS_WORKFLOW}
.dockerignore
Dockerfile.dockerignore
.gitignore
**/.gitignore
Dockerfile
Makefile
**/Makefile"

# The rehearsal job that provisions the contracts toolchain, and the CI job's
# steps it has to agree with. The lint job around them pins a different release
# on purpose: a resolution that searched a whole workflow instead of the job a
# parity claim names would read that one, or trip over having found two.
DEFAULT_SOLIDITY_JOB="  ${SOLIDITY_PROOFS_JOB}:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: ${SETUP_NODE_ACTION}@v4
        with:
          node-version: \"18.15.0\""
DEFAULT_CONTRACTS_STEPS="      - uses: actions/checkout@v3
      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"18.15.0\"
      - uses: ./.github/actions/install-yarn-deps
        with:
          working-directory: ./solidity/ecdsa"

# The two scaffold workflows every fixture carries: the dispatch whose build
# step names the Dockerfile and the context it is compiled from, and the lint
# whose path filters have to cover every input that naming depends on. The
# mirror check resolves both before it compiles a single ignore rule, so a
# fixture without them would prove nothing about the rules it does carry.
#
# The build step's body and the filter entries are given whole so a case can
# shape exactly the drift it means to prove. The step that follows the build
# one carries a block scalar on purpose: its content is indented past the
# step's own keys, and a parser that read it as structure would slice the
# build step's inputs somewhere else entirely.

# The step the lint fixture's job runs the analysis from, and the shape of the
# job around it, unless a case is proving a drift in one of them. The
# invocation sits in a block scalar under `run:` the way the checked-in one
# does, so the cases prove the placement over the shape it really has.
DEFAULT_LINT_JOB="  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        run: |
          EVIDENCE_DIR=/tmp/evidence \\
            ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}
      - name: Upload scaffold-lint evidence
        if: \${{ always() }}
        uses: actions/upload-artifact@v4"

write_scaffold_workflows() {
  local repo="$1" step="$2" filters="$3" entry
  local jobs="${4-${DEFAULT_SOLIDITY_JOB}}"
  mkdir -p "${repo}/$(dirname "${REHEARSAL_WORKFLOW}")"
  {
    printf 'name: Cutover Rehearsal\non:\n  workflow_dispatch:\njobs:\n'
    printf '  local-proofs:\n    runs-on: ubuntu-latest\n    steps:\n'
    printf '      - uses: actions/checkout@v4\n'
    printf '      - name: Build Docker Build Image\n'
    printf '%s\n' "${step}"
    printf '      - name: Run cutover gate local proofs\n'
    printf '        run: |\n'
    printf '          docker run go-build-env \\\n'
    printf '            ./scripts/release/pr4109/rehearse.sh local-proofs\n'
    [[ -n "${jobs}" ]] && printf '%s\n' "${jobs}"
  } >"${repo}/${REHEARSAL_WORKFLOW}"

  {
    printf 'name: Cutover Scaffold Lint\non:\n'
    printf '  push:\n    branches:\n      - main\n    paths:\n'
    while IFS= read -r entry; do
      [[ -n "${entry}" ]] && printf '      - "%s"\n' "${entry}"
    done <<<"${filters}"
    printf '  pull_request:\n    paths:\n'
    while IFS= read -r entry; do
      [[ -n "${entry}" ]] && printf '      - "%s"\n' "${entry}"
    done <<<"${filters}"
    printf 'jobs:\n%s\n' "${5-${DEFAULT_LINT_JOB}}"
  } >"${repo}/${SCAFFOLD_LINT_WORKFLOW}"
}

# The same build step and filters after the build has been moved onto another
# Dockerfile in another directory: the ignore file that name selects moves with
# it, and so does everything the gate has to run on.
ALT_BUILD_STEP="        uses: ${BUILD_ACTION}@v5
        with:
          target: build-docker
          context: .
          file: build/Alt.Dockerfile"
ALT_PATH_FILTERS="${SCAFFOLD_DIR}/**
${REHEARSAL_WORKFLOW}
${SCAFFOLD_LINT_WORKFLOW}
${CONTRACTS_WORKFLOW}
.dockerignore
build/Alt.Dockerfile.dockerignore
.gitignore
**/.gitignore
build/Alt.Dockerfile
Makefile
**/Makefile"

# Commit whatever a case has written into a built fixture. The resolution
# reads the workflows and the ignore rules from the commit, so an uncommitted
# drift would not exist as far as it is concerned.
commit_fixture() {
  (
    cd "$1"
    git_q add -Af
    git_q commit -q -m 'fixture drift'
  )
}

# Rewrite a built fixture's scaffold workflows, and commit them together with
# whatever else the case has staged.
recommit_scaffold_workflows() {
  local repo="$1" step="$2" filters="$3"
  write_scaffold_workflows "${repo}" "${step}" "${filters}" \
    "${4-${DEFAULT_SOLIDITY_JOB}}"
  commit_fixture "${repo}"
}

# The CI workflow the contracts stage reproduces. The job the claim names is
# surrounded by jobs pinning other releases, so a resolution that read the
# workflow instead of the job would resolve the wrong one — or, having found
# several, would have to guess.
write_contracts_workflow() {
  local repo="$1" steps="$2" job="${3-${CONTRACTS_JOB}}"
  mkdir -p "${repo}/$(dirname "${CONTRACTS_WORKFLOW}")"
  {
    printf 'name: Solidity ECDSA\non:\n  pull_request:\njobs:\n'
    printf '  contracts-lint:\n    runs-on: ubuntu-latest\n    steps:\n'
    printf '      - uses: actions/checkout@v3\n'
    printf '      - uses: %s@v3\n        with:\n' "${SETUP_NODE_ACTION}"
    printf '          node-version: "20.11.0"\n'
    printf '  %s:\n    runs-on: ubuntu-latest\n    steps:\n' "${job}"
    [[ -n "${steps}" ]] && printf '%s\n' "${steps}"
    printf '  contracts-publish:\n    runs-on: ubuntu-latest\n    steps:\n'
    printf '      - uses: actions/checkout@v3\n'
    printf '      - uses: %s@v3\n        with:\n' "${SETUP_NODE_ACTION}"
    printf '          node-version: "16.20.2"\n'
  } >"${repo}/${CONTRACTS_WORKFLOW}"
}

# A throwaway repository carrying just the two workflows the contracts
# toolchain claim is read out of.
make_toolchain_repo() {
  local repo="$1" contracts_steps="$2"
  mkdir -p "${repo}"
  (
    cd "${repo}"
    git_q init -q
    write_scaffold_workflows "${repo}" "${DEFAULT_BUILD_STEP}" \
      "${DEFAULT_PATH_FILTERS}" "${3-${DEFAULT_SOLIDITY_JOB}}"
    write_contracts_workflow "${repo}" "${contracts_steps}"
    git_q add -Af
    git_q commit -q -m 'toolchain fixture'
  )
}

# Lay down the alternate Dockerfile the cases move the build onto, beside the
# ignore file its name selects — a copy of the given rules, so a case can prove
# both that those rules are the ones read and that a drift in them is caught.
plant_alternate_dockerfile() {
  local repo="$1" ignore="$2"
  mkdir -p "${repo}/build"
  echo 'FROM scratch' >"${repo}/build/Alt.Dockerfile"
  cp "${ignore}" "${repo}/build/Alt.Dockerfile.dockerignore"
}

# A miniature of the real tree holding one representative of every family
# the classifier distinguishes: context-excluded paths, the protected
# committed generated code (gen/pb, gen/gen.go, gen/cmd/cmd.go), the
# regenerated binding and _address families, plain source, and ignore rules
# covering the image's build outputs.
make_origin() {
  local repo="${WORK}/origin"
  mkdir -p "${repo}"
  (
    cd "${repo}"
    git_q init -q
    printf '/keep-client\ntmp/\n/pkg/chain/**/gen/_contracts/\n/pkg/chain/**/gen/abi/*.abi\n' \
      >.gitignore
    mkdir -p .github/workflows .clusterfuzzlite docs scripts config \
      pkg/tbtc/gen/pb \
      pkg/chain/ethereum/beacon/gen/abi \
      pkg/chain/ethereum/beacon/gen/cmd \
      pkg/chain/ethereum/beacon/gen/contract \
      pkg/chain/ethereum/beacon/gen/_address \
      solidity/ecdsa
    echo 'jobs:' >.github/workflows/ci.yml
    echo 'fuzz build' >.clusterfuzzlite/build.sh
    echo 'FROM scratch' >Dockerfile
    echo '* @keep-network/core' >CODEOWNERS
    echo '= README' >README.adoc
    echo 'docs' >docs/index.adoc
    echo '#!/bin/sh' >scripts/helper.sh
    echo 'toml' >config/config.toml
    echo 'module example.com/m' >go.mod
    echo 'package main' >main.go
    echo 'package pb // committed protobuf bytes' \
      >pkg/tbtc/gen/pb/message.pb.go
    echo 'package gen // committed generator directives' \
      >pkg/chain/ethereum/beacon/gen/gen.go
    echo 'package cmd // committed root command' \
      >pkg/chain/ethereum/beacon/gen/cmd/cmd.go
    echo 'package cmd // committed binding command' \
      >pkg/chain/ethereum/beacon/gen/cmd/RandomBeacon.go
    echo 'package abi // committed binding abi' \
      >pkg/chain/ethereum/beacon/gen/abi/RandomBeacon.go
    echo 'package contract // committed binding' \
      >pkg/chain/ethereum/beacon/gen/contract/RandomBeacon.go
    touch pkg/chain/ethereum/beacon/gen/_address/.keep
    : >pkg/chain/ethereum/beacon/gen/_address/RandomBeacon
    echo 'contract A {}' >solidity/ecdsa/WalletRegistry.sol
    write_scaffold_workflows "${repo}" "${DEFAULT_BUILD_STEP}" \
      "${DEFAULT_PATH_FILTERS}"
    git_q add -A
    git_q commit -q -m 'fixture'
  )
  ORIGIN_SHA="$(git -C "${repo}" rev-parse HEAD)"
}

# A pristine clone of the origin: the dispatched checkout as CI sees it.
make_checkout() {
  local tree="$1"
  git_q clone -q --no-hardlinks "${WORK}/origin" "${tree}"
}

# Reshape a clone the way the Dockerfile builds the image: context-excluded
# paths never copied (ignore rules included), the binding and _address
# families rewritten from downloaded artifacts, the _address placeholder not
# recreated, and the gitignored build outputs present.
make_image_tree() {
  local tree="$1"
  make_checkout "${tree}"
  (
    cd "${tree}"
    rm -rf .gitignore .github Dockerfile CODEOWNERS README.adoc docs \
      scripts solidity
    rm -f pkg/chain/ethereum/beacon/gen/_address/.keep
    printf '0x1111111111111111111111111111111111111111' \
      >pkg/chain/ethereum/beacon/gen/_address/RandomBeacon
    echo 'package contract // regenerated from published artifacts' \
      >pkg/chain/ethereum/beacon/gen/contract/RandomBeacon.go
    echo 'package abi // regenerated from published artifacts' \
      >pkg/chain/ethereum/beacon/gen/abi/RandomBeacon.go
    echo 'package cmd // regenerated from published artifacts' \
      >pkg/chain/ethereum/beacon/gen/cmd/RandomBeacon.go
    echo 'binary bytes' >keep-client
    mkdir -p 'tmp/contracts/development/@keep-network/random-beacon'
    echo 'tarball bytes' \
      >'tmp/contracts/development/@keep-network/random-beacon/keep-network-random-beacon-2.1.0-dev.24.tgz'
    echo 'abi json' >pkg/chain/ethereum/beacon/gen/abi/RandomBeacon.abi
    mkdir -p pkg/chain/ethereum/beacon/gen/_contracts
    echo 'artifact json' \
      >pkg/chain/ethereum/beacon/gen/_contracts/RandomBeacon.json
  )
}

# A throwaway checkout carrying a given .dockerignore and one tracked path
# per family the verifier's build-context classification distinguishes:
# context-excluded paths, the protected committed generated code, the
# regenerated binding and _address families, a non-Go file inside a gen/
# tree, and plain source. The mirror cases commit the checked-in
# .dockerignore or a deliberate drift of it, so what they compare against is
# the real rule set.
#
# An optional third argument commits a Dockerfile-specific ignore file
# alongside the root one. The builder reads that file instead of the root
# .dockerignore whenever it exists, so the precedence cases hand the two
# files different rules and require the verifier to follow the build.
make_context_repo() {
  local repo="$1" ignore="$2" dockerfile_ignore="${3:-}"
  mkdir -p "${repo}"
  (
    cd "${repo}"
    git_q init -q
    cp "${ignore}" .dockerignore
    if [[ -n "${dockerfile_ignore}" ]]; then
      cp "${dockerfile_ignore}" Dockerfile.dockerignore
    fi
    mkdir -p .github/workflows .clusterfuzzlite docs infrastructure scripts \
      config solidity/ecdsa pkg/tbtc/gen/pb \
      pkg/chain/ethereum/beacon/gen/abi \
      pkg/chain/ethereum/beacon/gen/cmd \
      pkg/chain/ethereum/beacon/gen/_address
    echo 'jobs:' >.github/workflows/ci.yml
    echo 'fuzz build' >.clusterfuzzlite/build.sh
    echo 'FROM scratch' >Dockerfile
    echo '* @keep-network/core' >CODEOWNERS
    echo '= README' >README.adoc
    echo 'docs' >docs/index.adoc
    echo 'kind: Deployment' >infrastructure/kube.yaml
    echo '#!/bin/sh' >scripts/helper.sh
    echo 'toml' >config/config.toml
    echo 'contract A {}' >solidity/ecdsa/WalletRegistry.sol
    echo 'package main' >main.go
    echo 'package pb' >pkg/tbtc/gen/pb/message.pb.go
    echo 'package gen' >pkg/chain/ethereum/beacon/gen/gen.go
    echo 'abi:' >pkg/chain/ethereum/beacon/gen/Makefile
    echo 'package cmd' >pkg/chain/ethereum/beacon/gen/cmd/cmd.go
    echo 'package cmd' >pkg/chain/ethereum/beacon/gen/cmd/RandomBeacon.go
    echo 'package abi' >pkg/chain/ethereum/beacon/gen/abi/RandomBeacon.go
    : >pkg/chain/ethereum/beacon/gen/_address/RandomBeacon
    write_scaffold_workflows "${repo}" "${DEFAULT_BUILD_STEP}" \
      "${DEFAULT_PATH_FILTERS}"
    git_q add -Af
    git_q commit -q -m 'context fixture'
  )
}

# Derive a drifted .dockerignore from the checked-in one. A filter that
# removes nothing would make its case pass for the wrong reason — the rules
# it names having since been renamed or dropped — so an ineffective filter is
# reported as a failure instead of being silently tolerated.
drift_dockerignore() {
  local out="$1" filter="$2"
  grep -Ev -- "${filter}" "${CHECKED_IN_DOCKERIGNORE}" >"${out}" || true
  if cmp -s "${out}" "${CHECKED_IN_DOCKERIGNORE}"; then
    printf 'FAIL fixture: /%s/ removes no .dockerignore line; the case built \
on it would prove nothing\n' "${filter}"
    FAILED=$((FAILED + 1))
  fi
}

# Rewrite rules of the checked-in .dockerignore into an equivalent spelling —
# the cases below use it for the forms that only survive path cleaning. Like
# drift_dockerignore, a rewrite that matches nothing is a failure rather than
# a case that passes for having changed nothing.
rewrite_dockerignore() {
  local out="$1"
  shift
  local expr args=()
  for expr in "$@"; do args+=(-e "${expr}"); done
  sed "${args[@]}" "${CHECKED_IN_DOCKERIGNORE}" >"${out}"
  if cmp -s "${out}" "${CHECKED_IN_DOCKERIGNORE}"; then
    printf 'FAIL fixture: the rewrite rewrites no .dockerignore line; the \
case built on it would prove nothing\n'
    FAILED=$((FAILED + 1))
  fi
}

# Append extra rules to the checked-in .dockerignore. The cases use it for
# constructs the verifier must refuse outright, so what precedes them has to
# be the real rule set: a refusal reached before the real rules are read
# would prove nothing about the file the build actually applies.
extend_dockerignore() {
  local out="$1"
  shift
  cat "${CHECKED_IN_DOCKERIGNORE}" >"${out}"
  printf '%s\n' "$@" >>"${out}"
}

# Run verify_build_context_mirror against a throwaway repository in an
# isolated subshell so a fail/exit inside it never kills the test run;
# capture rc and combined output.
run_context_mirror() {
  local root="$1"
  set +e
  CASE_OUT="$(
    (
      # The sourced check reads this; shellcheck cannot see across the
      # source boundary, and the assignment stays in this subshell.
      # shellcheck disable=SC2034
      REPO_ROOT="${root}"
      verify_build_context_mirror
    ) 2>&1
  )"
  CASE_RC=$?
  set -e
}

# Run verify_contracts_toolchain_pin against a throwaway repository, in the
# same isolated shape as the mirror runner above.
run_toolchain_pin() {
  local root="$1"
  set +e
  CASE_OUT="$(
    (
      # shellcheck disable=SC2034
      REPO_ROOT="${root}"
      verify_contracts_toolchain_pin
    ) 2>&1
  )"
  CASE_RC=$?
  set -e
}

# Run verify_source_binding against a tree in an isolated subshell so a
# fail/exit inside the verifier never kills the test run; capture rc and
# combined output. Arguments: repo root, expected commit, binding mode.
run_verifier() {
  local root="$1" expected="$2" mode="$3"
  set +e
  CASE_OUT="$(
    (
      # The sourced verifier reads these three; shellcheck cannot see
      # across the source boundary.
      # shellcheck disable=SC2034
      REPO_ROOT="${root}"
      # shellcheck disable=SC2034
      PR4109_EXPECTED_SOURCE_COMMIT="${expected}"
      # shellcheck disable=SC2034
      PR4109_SOURCE_BINDING_MODE="${mode}"
      verify_source_binding
    ) 2>&1
  )"
  CASE_RC=$?
  set -e
}

# Assert a file's post-run bytes. Restoration must leave exactly the
# committed bytes on disk — those are the bytes any following test
# compiles — so the proof is the file content, not the verifier's output.
assert_file_is() {
  local desc="$1" file="$2" want="$3"
  if [[ ! -f "${file}" ]]; then
    printf 'FAIL %s: %s is missing\n' "${desc}" "${file}"
    FAILED=$((FAILED + 1))
    return
  fi
  local got
  got="$(cat "${file}")"
  if [[ "${got}" != "${want}" ]]; then
    printf 'FAIL %s: %s holds [%s], want [%s]\n' \
      "${desc}" "${file}" "${got}" "${want}"
    FAILED=$((FAILED + 1))
    return
  fi
  printf 'ok   %s\n' "${desc}"
  PASS=$((PASS + 1))
}

# Assert the captured rc and that the output matches every given pattern.
check() {
  local desc="$1" want_rc="$2"
  shift 2
  if [[ "${CASE_RC}" -ne "${want_rc}" ]]; then
    printf 'FAIL %s: rc %s, want %s\n--- output ---\n%s\n--------------\n' \
      "${desc}" "${CASE_RC}" "${want_rc}" "${CASE_OUT}"
    FAILED=$((FAILED + 1))
    return
  fi
  local pattern
  for pattern in "$@"; do
    if ! printf '%s\n' "${CASE_OUT}" | grep -Eq -- "${pattern}"; then
      printf 'FAIL %s: output missing /%s/\n--- output ---\n%s\n--------------\n' \
        "${desc}" "${pattern}" "${CASE_OUT}"
      FAILED=$((FAILED + 1))
      return
    fi
  done
  printf 'ok   %s\n' "${desc}"
  PASS=$((PASS + 1))
}

make_origin

# --- exact mode -------------------------------------------------------------

T="${WORK}/exact-clean"
make_checkout "${T}"
run_verifier "${T}" "${ORIGIN_SHA}" ""
check "exact: pristine dispatched checkout passes" 0 \
  "verified against the dispatched SHA"

T="${WORK}/exact-dirty"
make_checkout "${T}"
echo tampered >>"${T}/main.go"
run_verifier "${T}" "${ORIGIN_SHA}" ""
check "exact: any divergence fails" 1 "tree diverges"

run_verifier "${T}" "" ""
check "unbound: dirty tree stamps -dirty instead of failing" 0 "dirty"

T="${WORK}/exact-mismatch"
make_checkout "${T}"
run_verifier "${T}" "0000000000000000000000000000000000000000" ""
check "exact: dispatched-SHA mismatch fails" 1 "source binding mismatch"

T="${WORK}/exact-badmode"
make_checkout "${T}"
run_verifier "${T}" "${ORIGIN_SHA}" "trust-me"
check "unknown binding mode fails" 1 "unknown PR4109_SOURCE_BINDING_MODE"

# --- build-image mode -------------------------------------------------------

T="${WORK}/img-clean"
make_image_tree "${T}"
run_verifier "${T}" "${ORIGIN_SHA}" build-image
check "build-image: the image's designed divergence passes, restored" 0 \
  "verified against the dispatched SHA inside the build image" \
  "9 context-excluded absence\(s\); 5 regenerated tracked file\(s\) restored" \
  "gen/contract/RandomBeacon\.go committed sha256 [0-9a-f]{64} \(pre-restore image sha256 [0-9a-f]{64}\)" \
  "gen/_address/RandomBeacon committed sha256 [0-9a-f]{64} \(pre-restore image sha256 [0-9a-f]{64}\)" \
  "gen/_address/\.keep committed sha256 [0-9a-f]{64} \(absent from the image\)" \
  "resolved contract artifact tarballs" \
  "keep-network-random-beacon-2\.1\.0-dev\.24\.tgz sha256 [0-9a-f]{64}"
assert_file_is "build-image: the tested contract binding is the committed \
bytes after verification" \
  "${T}/pkg/chain/ethereum/beacon/gen/contract/RandomBeacon.go" \
  'package contract // committed binding'
assert_file_is "build-image: the tested _address value is the committed \
bytes after verification" \
  "${T}/pkg/chain/ethereum/beacon/gen/_address/RandomBeacon" \
  ''

T="${WORK}/img-deletions-only"
make_checkout "${T}"
(cd "${T}" && rm -rf .gitignore .github Dockerfile CODEOWNERS README.adoc \
  docs scripts solidity)
run_verifier "${T}" "${ORIGIN_SHA}" build-image
check "build-image: expected context-excluded absences alone pass" 0 \
  "9 context-excluded absence\(s\); 0 regenerated tracked file\(s\) restored"

T="${WORK}/img-evil-bindings"
