# --- scaffold lint: which changes really reach the gate ---------------------
#
# Everything above rests on that gate running, and a filter list read as a set
# of names on triggers read as a count says it does in states where it does
# not. So these cases hold the reading itself: the required inputs are the ones
# the commit carries rather than a list kept by hand, the filters are read the
# way the workflow parser reads them — in order, last match deciding — and a
# trigger is read for the changes it actually fires on rather than for being
# spelled push or pull_request.
#
# They run the gate on its own, without the mirror behind it: what is being
# proved here is which changes reach it, and a case that had to keep a whole
# build context consistent to say so would prove that less clearly.

# One representative of every class the required-input derivation reads out of
# a commit, so each of the removal cases below has something real to uncover:
# the scaffold's own files (a script, a data file, and one a directory deep),
# the build inputs, and the root and nested ignore and build rules.
make_lint_repo() {
  local repo="$1"
  mkdir -p "${repo}"
  (
    cd "${repo}"
    git_q init -q
    mkdir -p "${SCAFFOLD_DIR}/deploy" pkg/chain/gen solidity
    echo 'FROM scratch' >Dockerfile
    printf '.git\n' >.dockerignore
    printf '/keep-client\n' >.gitignore
    printf 'build/\n' >solidity/.gitignore
    printf 'all:\n\t@true\n' >Makefile
    printf 'abi:\n\t@true\n' >pkg/chain/gen/Makefile
    echo '#!/usr/bin/env bash' >"${SCAFFOLD_DIR}/rehearse.sh"
    echo '{}' >"${SCAFFOLD_DIR}/release-manifest.json"
    echo 'services: {}' >"${SCAFFOLD_DIR}/deploy/compose.yaml"
    write_contracts_workflow "${repo}" "${DEFAULT_CONTRACTS_STEPS}"
    write_scaffold_workflows "${repo}" "${DEFAULT_BUILD_STEP}" \
      "${DEFAULT_PATH_FILTERS}"
    git_q add -Af
    git_q commit -q -m 'lint fixture'
  )
}

# The path-filter block one trigger carries, at a given indentation. The
# trigger cases build `on:` bodies a line at a time so they can shape one
# trigger without disturbing the other, and every filtered trigger needs this
# list written out under it.
lint_paths_block() {
  local indent="$1" filters="$2" entry
  printf '%*spaths:\n' "${indent}" ''
  while IFS= read -r entry; do
    [[ -n "${entry}" ]] && printf '%*s- "%s"\n' "$((indent + 2))" '' "${entry}"
  done <<<"${filters}"
}

# Rewrite a lint fixture's scaffold-lint workflow around a given `on:` body
# and, optionally, a given jobs block, then commit it. Both are given whole
# because what these cases vary is one of those two shapes.
recommit_lint_workflow() {
  local repo="$1" on_body="$2"
  {
    printf 'name: Cutover Scaffold Lint\non:\n'
    # Whole-line, because command substitution took the body's last newline.
    printf '%s\n' "${on_body}"
    printf 'jobs:\n%s\n' "${3-${DEFAULT_LINT_JOB}}"
  } >"${repo}/${SCAFFOLD_LINT_WORKFLOW}"
  commit_fixture "${repo}"
}

# The default `on:` body, for the cases varying only the jobs block under it.
lint_default_on() {
  printf '  push:\n    branches:\n      - main\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
  printf '  pull_request:\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
}

# Run the gate on its own against a throwaway repository, in the same isolated
# shape as the mirror runner and in the same order the mirror runs it: which
# changes reach the gate, then whether reaching it runs anything. The build
# identity is resolved first because the required inputs include the
# Dockerfile the build really compiles.
run_lint_gate() {
  local root="$1"
  set +e
  CASE_OUT="$(
    (
      # shellcheck disable=SC2034
      REPO_ROOT="${root}"
      resolve_build_step_identity
      verify_scaffold_lint_path_filters
      verify_scaffold_lint_runs_analysis
    ) 2>&1
  )"
  CASE_RC=$?
  set -e
}

T="${WORK}/lint-covers-every-class"
make_lint_repo "${T}"
run_lint_gate "${T}"
check "scaffold lint: the checked-in filter shape covers every input class \
the commit carries" 0 \
  "runs on every change to the 13 tracked input\(s\)" \
  "on all 2 push/pull-request trigger\(s\)"

# One removal per class the derivation reads out of the commit. Each one is a
# path the gate has to run on that no other entry in the list covers, so a
# check trusting the list by inspection passes every one of them.

T="${WORK}/lint-drops-scaffold"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "$(grep -vxF "${SCAFFOLD_DIR}/**" <<<"${DEFAULT_PATH_FILTERS}")"
run_lint_gate "${T}"
check "scaffold lint: a filter list that stops covering the scaffold's own \
files fails closed" 1 \
  "does not cover ${SCAFFOLD_DIR}/rehearse\.sh" \
  "does not cover ${SCAFFOLD_DIR}/deploy/compose\.yaml" \
  "does not cover ${SCAFFOLD_DIR}/release-manifest\.json"

T="${WORK}/lint-drops-root-gitignore"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "$(grep -vxF '.gitignore' <<<"${DEFAULT_PATH_FILTERS}")"
run_lint_gate "${T}"
check "scaffold lint: a filter list that stops covering the root ignore rules \
fails closed" 1 \
  "the push filter list does not cover \.gitignore" \
  "the pull_request filter list does not cover \.gitignore"

# The root entry does not cover a nested file and the nested entry does not
# cover the root one, so dropping either leaves rules that decide what counts
# as divergence changing without this gate running.
T="${WORK}/lint-drops-nested-gitignore"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "$(grep -vxF '**/.gitignore' <<<"${DEFAULT_PATH_FILTERS}")"
run_lint_gate "${T}"
check "scaffold lint: a filter list that stops covering nested ignore rules \
fails closed" 1 \
  "does not cover solidity/\.gitignore"

T="${WORK}/lint-drops-root-makefile"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "$(grep -vxF 'Makefile' <<<"${DEFAULT_PATH_FILTERS}")"
run_lint_gate "${T}"
check "scaffold lint: a filter list that stops covering the root Makefile \
fails closed" 1 \
  "the push filter list does not cover Makefile" \
  "the pull_request filter list does not cover Makefile"

# The regeneration whose output the verifier explains absences by is run by the
# per-package gen Makefiles, not by the root one.
T="${WORK}/lint-drops-nested-makefile"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "$(grep -vxF '**/Makefile' <<<"${DEFAULT_PATH_FILTERS}")"
run_lint_gate "${T}"
check "scaffold lint: a filter list that stops covering the gen Makefiles \
fails closed" 1 \
  "does not cover pkg/chain/gen/Makefile"

# Order decides. An entry listed and then negated further down covers nothing,
# and a check reading the list for membership cannot see the difference.
T="${WORK}/lint-negates-required"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "${DEFAULT_PATH_FILTERS}
!${SCAFFOLD_DIR}/**"
run_lint_gate "${T}"
check "scaffold lint: a required path listed and then negated fails closed" 1 \
  "does not cover ${SCAFFOLD_DIR}/rehearse\.sh"

# And the same reading has to accept the other order: a negation a later entry
# re-includes over excludes nothing.
T="${WORK}/lint-negation-reincluded"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "${DEFAULT_PATH_FILTERS}
!${SCAFFOLD_DIR}/**
${SCAFFOLD_DIR}/**"
run_lint_gate "${T}"
check "scaffold lint: a negation a later entry re-includes over excludes \
nothing" 0 \
  "runs on every change to the 13 tracked input\(s\)"

# A negation that misses every required input is not a hole, and reporting one
# would make the check something a maintainer routes around.
T="${WORK}/lint-negation-elsewhere"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "${DEFAULT_PATH_FILTERS}
!docs/**"
run_lint_gate "${T}"
check "scaffold lint: a negation covering nothing required is accepted" 0 \
  "runs on every change to the 13 tracked input\(s\)"

# `?` and `+` quantify the character before them in this grammar rather than
# standing for one of any character, so a required path measured against
# either would be measured wrong.
T="${WORK}/lint-unmodelled-pattern"
make_lint_repo "${T}"
recommit_scaffold_workflows "${T}" "${DEFAULT_BUILD_STEP}" \
  "${DEFAULT_PATH_FILTERS}
Dockerfile?"
run_lint_gate "${T}"
check "scaffold lint: a path filter this script has no reading for fails \
closed" 1 \
  "filters on \[Dockerfile\?\], whose \[\?\] this script has no reading for"

# The hole a trigger count cannot see: push fires only after a branch has
# already moved, so a push-only gate never runs on the change under review.
T="${WORK}/lint-push-only"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(
  printf '  push:\n    branches:\n      - main\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
)"
run_lint_gate "${T}"
check "scaffold lint: a gate running on pushes but no pull request fails \
closed" 1 \
  "runs on no pull request"

# A base-branch restriction exempts every pull request into any other branch,
# which is exactly where a release branch's changes land.
T="${WORK}/lint-pr-branch-restricted"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(
  printf '  pull_request:\n    branches:\n      - main\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
)"
run_lint_gate "${T}"
check "scaffold lint: a pull_request trigger restricted to one base branch \
fails closed" 1 \
  "restricts its pull_request trigger with branches"

T="${WORK}/lint-pr-branch-excluded"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(
  printf '  pull_request:\n    branches-ignore:\n      - "release/**"\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
)"
run_lint_gate "${T}"
check "scaffold lint: a pull_request trigger excluding a branch family fails \
closed" 1 \
  "restricts its pull_request trigger with branches-ignore"

# The subtler one: without synchronize the gate runs when the pull request
# opens and never again on what is pushed into it afterwards.
T="${WORK}/lint-pr-types-narrowed"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(
  printf '  pull_request:\n    types:\n      - opened\n      - reopened\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
)"
run_lint_gate "${T}"
check "scaffold lint: a pull_request trigger narrowed away from synchronize \
fails closed" 1 \
  "activity types missing synchronize"

# Widening past the default set leaves every state the gate already ran in
# still covered, so it is accepted.
T="${WORK}/lint-pr-types-widened"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(
  printf '  pull_request:\n    types:\n      - opened\n      - synchronize\n'
  printf '      - reopened\n      - ready_for_review\n'
  lint_paths_block 4 "${DEFAULT_PATH_FILTERS}"
)"
run_lint_gate "${T}"
check "scaffold lint: a pull_request trigger widened past the default types \
is accepted" 0 \
  "runs on every change to the 13 tracked input\(s\)"

# A push trigger restricted to one branch is not a hole: the pull_request
# trigger beside it is what holds the merge, and refusing this would only push
# maintainers to delete the push trigger instead.
T="${WORK}/lint-push-branch-restricted"
make_lint_repo "${T}"
run_lint_gate "${T}"
check "scaffold lint: a push trigger restricted to one branch is accepted \
beside an unrestricted pull_request" 0 \
  "on all 2 push/pull-request trigger\(s\)"

# Everything above says when the gate runs. None of it says that reaching it
# runs anything: a workflow firing on every change to every input while its
# job no longer invokes the analysis, or invokes it behind a condition, or
# lets it fail without failing the run, is the same ungated state spelled
# differently — and it passes every check above.

T="${WORK}/lint-runs-nothing"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4"
run_lint_gate "${T}"
check "scaffold lint: a gate whose job no longer runs the analysis fails \
closed" 1 \
  "no longer runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}" \
  "checking none of them"

# Two invocations are two placements, and the conditions read below belong to
# one step; guessing which would be guessing at the answer.
T="${WORK}/lint-runs-twice"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${DEFAULT_LINT_JOB}
  scaffold-lint-again:
    runs-on: ubuntu-latest
    steps:
      - run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: a workflow running the analysis twice fails closed" 1 \
  "${SCAFFOLD_LINT_STAGE} 2 times"

T="${WORK}/lint-step-conditioned"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        if: \${{ github.actor != 'dependabot[bot]' }}
        run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: a conditioned analysis step fails closed" 1 \
  "conditions the step running ${SCAFFOLD_LINT_STAGE}"

# The same hole one level out, where a check reading only the step would miss
# it entirely.
T="${WORK}/lint-job-conditioned"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    if: \${{ github.event_name == 'push' }}
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: a conditioned analysis job fails closed" 1 \
  "conditions the job \[scaffold-lint\] running ${SCAFFOLD_LINT_STAGE}"

T="${WORK}/lint-step-survivable"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        continue-on-error: true
        run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: an analysis step allowed to fail gates nothing" 1 \
  "lets the step running ${SCAFFOLD_LINT_STAGE} fail without failing the run"

T="${WORK}/lint-job-survivable"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    continue-on-error: true
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: an analysis job allowed to fail gates nothing" 1 \
  "lets the job \[scaffold-lint\] running ${SCAFFOLD_LINT_STAGE} fail"

# Spelled out as the no-op it is, it changes nothing and is accepted; refusing
# it would be refusing the shape rather than the hole.
T="${WORK}/lint-survivable-false"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        continue-on-error: false
        run: ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: an analysis step declared unsurvivable is accepted" 0 \
  "runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE} unconditionally"

# A condition on some other step is not a condition on this one — the
# checked-in workflow uploads its evidence under `if: always()` precisely so a
# failing analyzer's log survives, and refusing that would be refusing the
# shape that makes the gate diagnosable.
T="${WORK}/lint-other-step-conditioned"
make_lint_repo "${T}"
run_lint_gate "${T}"
check "scaffold lint: a condition on a step beside the analysis is not a \
condition on it" 0 \
  "runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE} unconditionally"

# Everything above establishes that the text is there and that neither the step
# nor the job is excused. None of it says the text is a command: a workflow can
# carry the invocation in a step name, print it, test it, or run it and throw
# its exit status away, and every one of those satisfies the checks above while
# gating exactly nothing. So the cases below are the false positives — the
# shapes a search for matching text would have called a run.

# A step runs its `run:` body and nothing else. Named in a step title, in an
# `env:` value, or in an action's inputs, the invocation is a label on a step
# that runs nothing at all.
LINT_JOB_HEAD="  scaffold-lint:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4"
LINT_INVOCATION="./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"

T="${WORK}/lint-named-not-run"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: ${LINT_INVOCATION}
        run: true"
run_lint_gate "${T}"
check "scaffold lint: the invocation in a step name runs nothing" 1 \
  "no longer runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"

T="${WORK}/lint-env-not-run"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        env:
          ANALYSIS: ${LINT_INVOCATION}
        run: true"
run_lint_gate "${T}"
check "scaffold lint: the invocation in an environment value runs nothing" 1 \
  "no longer runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE}"

# Printing the command is the cheapest way to leave the text in place while
# retiring the gate, and the step then reports the printer's exit status.
T="${WORK}/lint-echoed"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: echo ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: an echoed invocation is not a run of it" 1 \
  "does not run ${SCAFFOLD_LINT_STAGE} as a command of its own" \
  "its command word is \[echo\]"

# Captured rather than run: the status the step reports is the assignment's,
# which succeeds however the analysis ends.
T="${WORK}/lint-substituted"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: OUT=\$(${LINT_INVOCATION})"
run_lint_gate "${T}"
check "scaffold lint: an invocation captured in a substitution fails closed" 1 \
  "a command substitution"

# The two spellings that leave the analysis running and discard what it says.
T="${WORK}/lint-status-swallowed"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: ${LINT_INVOCATION} || true"
run_lint_gate "${T}"
check "scaffold lint: an invocation whose failure is excused in shell fails \
closed" 1 \
  "a conditional chain"

T="${WORK}/lint-piped"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: ${LINT_INVOCATION} | tee analysis.log"
run_lint_gate "${T}"
check "scaffold lint: a piped invocation reports the pipeline's status" 1 \
  "a pipeline"

# A shell condition is the same hole as a step-level `if:`, one layer down
# where the YAML keys this parser reads say nothing about it.
T="${WORK}/lint-shell-conditioned"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: |
          if [ -n \"\${ANALYZE:-}\" ]
          then
            ${LINT_INVOCATION}
          fi"
run_lint_gate "${T}"
check "scaffold lint: an invocation inside a shell condition fails closed" 1 \
  "the compound-statement word \[if\]"

# Read but never executed: the body runs to the end and the step succeeds
# having analyzed nothing.
T="${WORK}/lint-noexec"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: |
          set -n
          ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: a shell option retiring the body fails closed" 1 \
  "the shell builtin \[set\]"

# A step reports its last command's status, so anything after the invocation
# decides what a failing analysis is reported as.
T="${WORK}/lint-trailing-command"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: |
          ${LINT_INVOCATION}
          echo done"
run_lint_gate "${T}"
check "scaffold lint: a command after the invocation takes over its status" 1 \
  "with 1 command\(s\) after it"

# A stage argument the analysis does not take is a different run of a different
# thing, whatever the matching text says.
T="${WORK}/lint-extra-argument"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: ${LINT_INVOCATION} --dry-run"
run_lint_gate "${T}"
check "scaffold lint: an invocation carrying a further argument fails \
closed" 1 \
  "it carries the further argument \[--dry-run\]"

# A folded scalar hands the shell a joining of its lines that this parser does
# not perform, so what would run there is not what the lines say.
T="${WORK}/lint-folded"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: >
          ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: a folded run body is refused rather than read" 1 \
  "the block scalar header \[>\]"

# The runner writes an expression's value into this shell before the shell
# parses it, so an expression carrying pull-request text writes the command.
T="${WORK}/lint-expression-injected"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: \${{ github.event.inputs.prefix }} ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: an invocation written by an untrusted expression fails \
closed" 1 \
  "the workflow expression \[github\.event\.inputs\.prefix\]"

# The shape the checked-in step really has: a runner-owned expression in an
# assignment ahead of the invocation, and work done before it. Refusing this
# would be refusing the workflow this gate exists to hold.
T="${WORK}/lint-runner-expression"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: |
          mkdir -p \${{ github.workspace }}/rehearsal-evidence
          EVIDENCE_DIR=\${{ github.workspace }}/rehearsal-evidence \\
            ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: a runner-owned expression ahead of the invocation is \
accepted" 0 \
  "runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE} unconditionally"

# The invocation continued across two lines is one command, so a reading that
# counted raw lines would find neither the run nor its shape.
T="${WORK}/lint-continued-invocation"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        run: |
          ./${SCAFFOLD_DIR}/${SCAFFOLD_ENTRYPOINT} \\
            ${SCAFFOLD_LINT_STAGE}"
run_lint_gate "${T}"
check "scaffold lint: an invocation continued across lines is one run" 0 \
  "runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE} unconditionally"

# Naming another interpreter leaves every line of the body exactly as it was
# and retires all of it, which no reading of the shell alone would show.
T="${WORK}/lint-shell-replaced"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        shell: cat {0}
        run: ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: a step handed to another interpreter fails closed" 1 \
  "hands the step running ${SCAFFOLD_LINT_STAGE} to \[cat \{0\}\]"

# Spelled as the runner's own default it changes nothing, so it is accepted;
# refusing it would be refusing the shape rather than the hole.
T="${WORK}/lint-shell-bash"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "${LINT_JOB_HEAD}
      - name: Analyze the rehearsal scaffold
        shell: bash
        run: ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: a step naming the runner's own shell is accepted" 0 \
  "runs ${SCAFFOLD_ENTRYPOINT} ${SCAFFOLD_LINT_STAGE} unconditionally"

# The same substitution set a level or two away from the step it retires.
T="${WORK}/lint-job-defaults"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)" \
  "  scaffold-lint:
    runs-on: ubuntu-latest
    defaults:
      run:
        shell: cat {0}
    steps:
      - uses: actions/checkout@v4
      - name: Analyze the rehearsal scaffold
        run: ${LINT_INVOCATION}"
run_lint_gate "${T}"
check "scaffold lint: job defaults deciding what runs the body fail closed" 1 \
  "sets defaults on the job \[scaffold-lint\] running ${SCAFFOLD_LINT_STAGE}"

T="${WORK}/lint-workflow-defaults"
make_lint_repo "${T}"
recommit_lint_workflow "${T}" "$(lint_default_on)
defaults:
  run:
    shell: cat {0}"
run_lint_gate "${T}"
check "scaffold lint: workflow-wide defaults deciding what runs the body fail \
closed" 1 \
  "sets workflow-wide defaults"

# --- contracts toolchain: the parity the stage's evidence claims ------------
#
# The contracts stage's log says it reproduces one named CI job, and that claim
# holds only while the stage and the dispatch that provisions it run the
# toolchain that job pins. Restated as a constant the claim survives the job
# moving and goes on being made about a run that no longer reproduces
# anything, so it is read out of the job instead — from the job the claim
# names, not from the workflow around it, and never from a pin loose enough to
# let the runner decide.

T="${WORK}/toolchain-agrees"
make_toolchain_repo "${T}" "${DEFAULT_CONTRACTS_STEPS}"
run_toolchain_pin "${T}"
check "contracts toolchain: the named job's pin is the one both sides are \
held to" 0 \
  "both pin Node 18\.15\.0"

# The jobs on either side of the named one pin other releases, so a resolution
# reading the workflow rather than the job would resolve one of those.
T="${WORK}/toolchain-job-scope"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"20.11.0\"" \
  "  ${SOLIDITY_PROOFS_JOB}:
    runs-on: ubuntu-latest
    steps:
      - uses: ${SETUP_NODE_ACTION}@v4
        with:
          node-version: \"20.11.0\""
run_toolchain_pin "${T}"
check "contracts toolchain: the pin is read from the named job, not its \
neighbours" 0 \
  "both pin Node 20\.11\.0"

T="${WORK}/toolchain-rehearsal-drift"
make_toolchain_repo "${T}" "${DEFAULT_CONTRACTS_STEPS}" \
  "  ${SOLIDITY_PROOFS_JOB}:
    runs-on: ubuntu-latest
    steps:
      - uses: ${SETUP_NODE_ACTION}@v4
        with:
          node-version: \"20.11.0\""
run_toolchain_pin "${T}"
check "contracts toolchain: a dispatch provisioning another release fails \
closed" 1 \
  "provisions Node 20\.11\.0 while" \
  "pins 18\.15\.0" \
  "evidence produced on another toolchain is not its evidence"

# The direction the constant made invisible: CI moves, the scaffold does not.
T="${WORK}/toolchain-ci-bumped"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"22.11.0\""
run_toolchain_pin "${T}"
check "contracts toolchain: a bump in CI the scaffold has not followed fails \
closed" 1 \
  "provisions Node 18\.15\.0 while" \
  "pins 22\.11\.0"

T="${WORK}/toolchain-no-pin"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          cache: yarn"
run_toolchain_pin "${T}"
check "contracts toolchain: a job taking whatever the runner ships fails \
closed" 1 \
  "pins no node-version"

T="${WORK}/toolchain-range"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"18.x\""
run_toolchain_pin "${T}"
check "contracts toolchain: a pin loose enough for the runner to choose fails \
closed" 1 \
  "pins node-version \[18\.x\], which is not one exact release"

T="${WORK}/toolchain-expression"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \${{ inputs.node }}"
run_toolchain_pin "${T}"
check "contracts toolchain: a release decided at dispatch time fails closed" 1 \
  "writes its node-version as a workflow expression"

T="${WORK}/toolchain-two-steps"
make_toolchain_repo "${T}" "      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"18.15.0\"
      - uses: ${SETUP_NODE_ACTION}@v3
        with:
          node-version: \"20.11.0\""
run_toolchain_pin "${T}"
check "contracts toolchain: a job setting up Node twice fails closed" 1 \
  "has 2 actions/setup-node steps"

T="${WORK}/toolchain-no-step"
make_toolchain_repo "${T}" "      - uses: actions/checkout@v3"
run_toolchain_pin "${T}"
check "contracts toolchain: a job that no longer sets up Node fails closed" 1 \
  "has no actions/setup-node step"

T="${WORK}/toolchain-job-renamed"
make_toolchain_repo "${T}" "${DEFAULT_CONTRACTS_STEPS}"
write_contracts_workflow "${T}" "${DEFAULT_CONTRACTS_STEPS}" "contracts-build"
commit_fixture "${T}"
run_toolchain_pin "${T}"
check "contracts toolchain: a named job that no longer exists fails closed" 1 \
  "has no contracts-build-and-test job"

T="${WORK}/toolchain-rehearsal-job-gone"
make_toolchain_repo "${T}" "${DEFAULT_CONTRACTS_STEPS}" ""
run_toolchain_pin "${T}"
check "contracts toolchain: a dispatch with no contracts job at all fails \
closed" 1 \
  "has no solidity-proofs job"

T="${WORK}/toolchain-workflow-absent"
make_toolchain_repo "${T}" "${DEFAULT_CONTRACTS_STEPS}"
(cd "${T}" && git_q rm -q "${CONTRACTS_WORKFLOW}" &&
  git_q commit -q -m 'drop the contracts workflow')
run_toolchain_pin "${T}"
check "contracts toolchain: a commit carrying no contracts workflow fails \
closed" 1 \
  "carries no \.github/workflows/contracts-ecdsa\.yml"

# ----------------------------------------------------------------------------

printf '%d passed, %d failed\n' "${PASS}" "${FAILED}"
if [[ "${FAILED}" -ne 0 ]]; then
  exit 1
fi
